const ASSET_NAME = /^[A-Za-z0-9-]+_[A-Za-z0-9-]+_[A-Za-z0-9-]+_[A-Za-z0-9-]+_[A-Za-z0-9-]+_[A-Za-z0-9-]+_(9x16|4x5|1x1)$/;
const PURCHASE_TYPES = ['omni_purchase', 'purchase', 'app_custom_event.fb_mobile_purchase', 'offsite_conversion.fb_pixel_purchase'];
const minSpend = Number($env.MITOSIS_MIN_SPEND || 20);
const targetRoas = Number($env.MITOSIS_TARGET_ROAS || 1);

const purchaseValue = (entries) => {
  for (const type of PURCHASE_TYPES) {
    const entry = (entries || []).find((candidate) => candidate.action_type === type);
    if (entry) {
      return Number(entry.value) || 0;
    }
  }
  return 0;
};

const ads = new Map();
for (const row of $input.all().flatMap((item) => item.json.data || [])) {
  const name = String(row.ad_name || '').trim();
  if (!ASSET_NAME.test(name)) {
    continue;
  }
  const spend = Number(row.spend) || 0;
  const ad = ads.get(name) || { ad_name: name, spend: 0, purchases: 0, revenue: 0 };
  ad.spend += spend;
  ad.purchases += purchaseValue(row.actions);
  ad.revenue += purchaseValue(row.purchase_roas) * spend;
  ads.set(name, ad);
}

const eligible = [...ads.values()]
  .filter((ad) => ad.spend >= minSpend)
  .map((ad) => ({ ...ad, roas: ad.spend ? ad.revenue / ad.spend : 0 }));
if (!eligible.length) {
  return [];
}

const ordered = eligible.map((ad) => ad.roas).sort((a, b) => a - b);
const median = ordered[Math.floor((ordered.length - 1) / 2)];
const roasBar = Math.max(targetRoas, median);
const scored = eligible.map((ad) => ({ ...ad, win: ad.purchases > 0 && ad.roas >= roasBar }));
const rows = scored.map((ad) => [ad.ad_name, ad.spend.toFixed(2), Math.round(ad.purchases), ad.roas.toFixed(3), ad.win ? 1 : 0].join(','));
const csv = ['ad_name,spend,purchases,roas,win', ...rows].join('\n') + '\n';
const day = new Date().toISOString().slice(0, 10);

return [
  {
    json: {
      ads: ads.size,
      eligible: scored.length,
      wins: scored.filter((ad) => ad.win).length,
      spend: Number(scored.reduce((sum, ad) => sum + ad.spend, 0).toFixed(2)),
      roas_bar: Number(roasBar.toFixed(3)),
      min_spend: minSpend,
    },
    binary: {
      results: {
        data: Buffer.from(csv, 'utf8').toString('base64'),
        mimeType: 'text/csv',
        fileName: `meta_results_${day}.csv`,
        fileExtension: 'csv',
      },
    },
  },
];

const stats = $('Score Ads').first().json;
const response = $input.first().json;
const factors = response.factors || (response.priors || {}).factors || {};
const archetypes = factors.archetype || factors.hook_archetype || [];

const toEntry = (name, arm) => ({
  name,
  mean: Number(arm.mean ?? arm.alpha / (arm.alpha + arm.beta)) || 0,
  wins: arm.wins || 0,
  trials: arm.trials || 0,
});

const ranked = Array.isArray(archetypes)
  ? archetypes.map((row) => toEntry(row.level || row.name, row))
  : Object.entries(archetypes).map(([name, arm]) => toEntry(name, arm));
const top = ranked.sort((a, b) => b.mean - a.mean).slice(0, 3);

const lines = [
  '*Mitosis learning loop* (Meta insights, last 7 days)',
  `${stats.ads} Mitosis ads found | ${stats.eligible} with at least $${stats.min_spend} spend | ${stats.wins} winners at ROAS >= ${stats.roas_bar}`,
  top.length ? 'Top hook archetypes now:' : 'No archetype priors came back yet.',
  ...top.map((entry, index) => `${index + 1}. ${entry.name}: ${(entry.mean * 100).toFixed(0)}% expected win rate (${entry.wins}/${entry.trials} wins)`),
];
if (top.length) {
  lines.push('The next experiment plans will lean toward these archetypes.');
}

return [{ json: { slack_text: lines.join('\n'), top } }];

